package tests

import (
	"context"
	"errors"

	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
)

type MockUserPropsRepo struct {
	ctx  context.Context
	data map[string]map[string]string
}

func (p *MockUserPropsRepo) userID() (string, error) {
	u, ok := request.UserFrom(p.ctx)
	if !ok || u.ID == "" {
		return "", errors.New("user is missing from context")
	}
	return u.ID, nil
}

func (p *MockUserPropsRepo) Put(key, value string) error {
	uid, err := p.userID()
	if err != nil {
		return err
	}
	if p.data[uid] == nil {
		p.data[uid] = make(map[string]string)
	}
	p.data[uid][key] = value
	return nil
}

func (p *MockUserPropsRepo) Get(key string) (string, error) {
	uid, err := p.userID()
	if err != nil {
		return "", err
	}
	if value, ok := p.data[uid][key]; ok {
		return value, nil
	}
	return "", model.ErrNotFound
}

func (p *MockUserPropsRepo) Delete(key string) error {
	uid, err := p.userID()
	if err != nil {
		return err
	}
	delete(p.data[uid], key)
	return nil
}

